"""
adventure.py - A text adventure engine supporting rooms, items, inventory, a two-word command parser, and save/load functionality via JSON.

Usage:
    python3 adventure.py          # Starts the adventure game

File layout:
- /work/adventure.py   (engine)
- /work/config.json    (game data: rooms/items)
- /work/savegame.json  (optional: created during gameplay)

"""
import json
import os
import sys

class Item:
    """Represents an item in the adventure game."""
    def __init__(self, key, name, description, portable=True):
        self.key = key
        self.name = name
        self.description = description
        self.portable = portable
    def __str__(self):
        return self.name

class Room:
    """Represents a room in the game world."""
    def __init__(self, key, name, description, exits, items=None):
        self.key = key
        self.name = name
        self.description = description
        self.exits = exits
        self.items = items if items else []
    def __str__(self):
        return self.name

class AdventureGame:
    """Main engine for the adventure game."""
    def __init__(self, config_path="config.json", save_path="savegame.json"):
        self.config_path = config_path
        self.save_path = save_path
        self.inventory = []
        self.rooms = {}
        self.items = {}
        self.current_room = None
        self.load_config()
        self.load_game()

    def load_config(self):
        """Loads rooms/items data from config file."""
        with open(self.config_path) as f:
            data = json.load(f)
        # Load items
        for k, v in data['items'].items():
            self.items[k] = Item(k, v['name'], v['description'], v.get('portable', True))
        # Load rooms
        for rk, rv in data['rooms'].items():
            items_in_room = [self.items[ik] for ik in rv.get('items',[])]
            self.rooms[rk] = Room(rk, rv['name'], rv['description'], rv['exits'], items_in_room)
        self.start_room = data['start_room']
        if self.current_room is None:
            self.current_room = self.rooms[self.start_room]

    def save_game(self):
        """Saves progress to a JSON file."""
        data = {
            'current_room': self.current_room.key,
            'inventory': [item.key for item in self.inventory],
            'rooms': {rk: [item.key for item in r.items] for rk, r in self.rooms.items()}
        }
        with open(self.save_path, 'w') as f:
            json.dump(data, f, indent=2)
        print('(Game saved.)')

    def load_game(self):
        """Loads progress from a saved game, if present."""
        if os.path.exists(self.save_path):
            with open(self.save_path) as f:
                data = json.load(f)
            self.current_room = self.rooms[data['current_room']]
            self.inventory = [self.items[k] for k in data['inventory']]
            for rk, ilist in data['rooms'].items():
                self.rooms[rk].items = [self.items[ik] for ik in ilist]

    def describe_current_room(self):
        room = self.current_room
        print(f"\n== {room.name} ==\n{room.description}")
        for item in room.items:
            print(f"You see: {item.name} - {item.description}")
        exits = ', '.join(room.exits.keys())
        print(f"Exits: {exits}")

    def show_inventory(self):
        if self.inventory:
            print('Inventory:')
            for item in self.inventory:
                print(f" {item.name} - {item.description}")
        else:
            print('You have nothing.')

    def parse_input(self, command: str):
        words = command.strip().split()
        if len(words) != 2:
            print('Type a two-word command, e.g. "go north" or "take key".')
            return None, None
        return words[0], words[1]

    def do_command(self, verb, obj):
        if verb == 'go':
            self.handle_go(obj)
        elif verb == 'take':
            self.handle_take(obj)
        elif verb == 'drop':
            self.handle_drop(obj)
        elif verb == 'look':
            self.handle_look(obj)
        elif verb == 'save':
            self.save_game()
        elif verb == 'load':
            self.load_game()
            print('(Game loaded.)')
            self.describe_current_room()
        elif verb == 'inv' and obj == 'now':
            self.show_inventory()
        else:
            print('Unknown command.')

    def handle_go(self, direction):
        if direction in self.current_room.exits:
            next_key = self.current_room.exits[direction]
            self.current_room = self.rooms[next_key]
            self.describe_current_room()
        else:
            print("You can't go that way.")

    def handle_take(self, item_key):
        items = [i for i in self.current_room.items if i.key == item_key]
        if items:
            item = items[0]
            if not item.portable:
                print("You can't take that.")
                return
            self.current_room.items.remove(item)
            self.inventory.append(item)
            print(f"Taken: {item.name}.")
        else:
            print('No such item here.')

    def handle_drop(self, item_key):
        for i, item in enumerate(self.inventory):
            if item.key == item_key:
                self.current_room.items.append(item)
                del self.inventory[i]
                print(f"Dropped: {item.name}.")
                return
        print('You do not have that.')

    def handle_look(self, obj):
        if obj == 'room':
            self.describe_current_room()
        else:
            for item in self.current_room.items + self.inventory:
                if item.key == obj or item.name.lower() == obj:
                    print(f"{item.name}: {item.description}")
                    return
            print('Nothing to look at.')

    def game_loop(self):
        print("Welcome to the Text Adventure! Type two-word commands. Try: go east, take key, inv now.")
        self.describe_current_room()
        while True:
            try:
                command = input("\n> ")
                if command.lower() in {"quit", "exit"}:
                    print('Goodbye!')
                    break
                verb, obj = self.parse_input(command)
                if verb:
                    self.do_command(verb, obj)
            except EOFError:
                print('\nExiting.')
                break

if __name__ == "__main__":
    game = AdventureGame()
    game.game_loop()
